// ── session / history storage (config rows, JSON) ──────────────────────────
const annWizKey = (uid) => `annwiz:${uid}`;
const annHistKey = (uid) => `annhist:${uid}`;

async function annConfigGet(key) {
  const rows = await db.select().from(configTable).where(eq(configTable.key, key)).limit(1).all();
  return rows[0]?.value ?? null;
}

async function loadAnnWiz(uid) {
  try {
    const raw = await annConfigGet(annWizKey(uid));
    if (!raw) return null;
    const s = JSON.parse(raw);
    if (!s || s.v !== 1 || !(Number(s.expiresAt) > Date.now())) return null;
    return s;
  } catch { return null; }
}

async function saveAnnWiz(uid, s) {
  s.expiresAt = Date.now() + ANN_WIZ_TTL_MS;
  await setConfig(annWizKey(uid), JSON.stringify(s));
}

async function clearAnnWiz(uid) {
  try {
    await db.delete(configTable).where(eq(configTable.key, annWizKey(uid))).run();
  } catch { /* already gone */ }
}

async function loadAnnHist(uid) {
  try {
    const raw = await annConfigGet(annHistKey(uid));
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch { return []; }
}

async function pushAnnHist(uid, entry) {
  const hist = await loadAnnHist(uid);
  hist.unshift(entry);
  await setConfig(annHistKey(uid), JSON.stringify(hist.slice(0, ANN_HIST_MAX)));
}

// ── token facts: the /scan path (GeckoTerminal) + DexScreener logo ────────
// fetchTokenByAddress (lib/market.js) is what /scan reads. The DexScreener
// token endpoint adds the logo URL (pairs[0].info.imageUrl) and is a
// fallback for name/symbol when GeckoTerminal has no pool for the token.
async function fetchAnnounceTokenFacts(address) {
  let name = null; let symbol = null; let priceUsd = null; let logoUrl = null;
  const gt = await fetchTokenByAddress(address).catch(() => null);
  if (gt) { name = gt.name; symbol = gt.symbol; priceUsd = gt.priceUsd ?? null; }
  try {
    const res = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${address}`);
    if (res && res.ok) {
      const j = await res.json().catch(() => null);
      const pairs = Array.isArray(j?.pairs) ? j.pairs : [];
      const pair = pairs.find((p) => String(p?.baseToken?.address ?? '').toLowerCase() === address.toLowerCase()) ?? pairs[0];
      if (pair) {
        name = name || pair.baseToken?.name || null;
        symbol = symbol || pair.baseToken?.symbol || null;
        logoUrl = pair.info?.imageUrl ?? null;
        if (priceUsd == null && pair.priceUsd != null && Number.isFinite(Number(pair.priceUsd))) priceUsd = Number(pair.priceUsd);
      }
    }
  } catch { /* best-effort */ }
  if (!name && !symbol) {
    // One retry of the scan path before refusing: GeckoTerminal's free
    // tier rate-limits in bursts (and DexScreener carries no pair at all
    // for some real tokens), so a single transient miss would otherwise
    // dead-end the wizard's front door on a perfectly good CA. The
    // DexScreener round-trip above spaces the retry naturally.
    const retry = await fetchTokenByAddress(address).catch(() => null);
    if (retry) { name = retry.name; symbol = retry.symbol; priceUsd = retry.priceUsd ?? null; }
  }
  if (!name && !symbol) return null;
  return { name: name || symbol, symbol: symbol || '', priceUsd, logoUrl };
}

// ── palette: deterministic from the token CA ───────────────────────────────
// Brand color "sampled from their logo" is impossible in this isolate —
// lib/pngcard.js is an encoder + rasterizers with NO image decoder, so
// logo bytes cannot be read back. The honest substitute: a stable palette
// hashed from the CA (same token → same colors every time; a poster
// re-roll rotates the hue a step). Owner mode uses the fixed PB palette.
function hslToRgb(h, s, l) {
  const sn = s / 100; const ln = l / 100;
  const k = (n) => (n + h / 30) % 12;
  const a = sn * Math.min(ln, 1 - ln);
  const f = (n) => ln - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  return [Math.round(f(0) * 255), Math.round(f(8) * 255), Math.round(f(4) * 255)];
}

function hashHue(str) {
  let h = 0;
  const s = String(str ?? '');
  for (let i = 0; i < s.length; i++) h = ((h * 31) + s.charCodeAt(i)) >>> 0;
  return h % 360;
}

function announcePalette(session) {
  if (session.mode === 'owner') return { bg: [10, 15, 24], band: [14, 44, 60], accent: [0, 200, 220] };
  const p = session.project ?? {};
  const roll = Math.max(1, Number(session.poster?.roll) || 1);
  const hue = (hashHue(String(p.address || p.name || 'announce').toLowerCase()) + (roll - 1) * 24) % 360;
  return { bg: hslToRgb(hue, 45, 6), band: hslToRgb(hue, 55, 15), accent: hslToRgb(hue, 85, 62) };
}

// ── poster spec + AI art prompt ────────────────────────────────────────────
export function posterSpecFor(session) {
  const p = session.project ?? {};
  const pal = announcePalette(session);
  const addr = p.address ? `${p.address.slice(0, 6)}...${p.address.slice(-4)}` : '';
  const footer = [p.symbol ? `$${String(p.symbol).toUpperCase()}` : '', p.address ? 'BASE' : '', addr]
    .filter(Boolean).join(' - ') || String(p.groupTitle || '').toUpperCase().slice(0, 34);
  return {
    name: p.name || 'Announcement',
    hook: session.hook || '',
    tag: session.mode === 'owner' ? 'POORBOYAI - ANNOUNCEMENT' : 'ANNOUNCEMENT',
    footer,
    // White-label law: a PB credit exists ONLY on owner-mode posters.
    credit: session.mode === 'owner' ? 'VIA @POORBOYAIBOT' : null,
    bg: pal.bg, band: pal.band, accent: pal.accent,
  };
}

function renderPosterBytes(session) {
  return renderAnnouncePoster(posterSpecFor(session));
}

function artPromptFor(session) {
  const p = session.project ?? {};
  const hook = session.hook || session.news || 'big news';
  if (session.mode === 'owner' && p.kind === 'pb') {
    return `Bold announcement artwork for PoorBoyAI featuring PB, a street-smart cartoon hustler mascot in a cap with a thick gold chain, celebrating big news: ${hook}. Neon cyan and deep navy palette, cinematic glow, energetic crypto street style. Absolutely no text, no letters, no words, no numbers.`;
  }
  return `Bold crypto announcement artwork for a token called ${p.name || 'a token'}${p.symbol ? ` ($${p.symbol})` : ''}, themed around this news: ${hook}. Dramatic cinematic lighting, rich saturated colors, abstract crypto energy, coins and light trails. Absolutely no text, no letters, no words, no numbers, no logos.`;
}

// ── the draft (deps.draft is the harness seam) ─────────────────────────────
export async function draftAnnouncement(project, news, deps = {}) {
  if (typeof deps.draft === 'function') return deps.draft(project, news);
  const lines = [`Name: ${project.name}`];
  if (project.symbol) lines.push(`Symbol: $${project.symbol}`);
  lines.push('Chain: Base');
  if (project.address) lines.push(`Contract address: ${project.address}`);
  if (project.priceUsd != null) lines.push(`Live price: $${project.priceUsd}`);
  if (project.groupTitle) lines.push(`Community group: ${project.groupTitle}`);
  try {
    const out = await askBrain(
      `VERIFIED PROJECT DATA (live):\n${lines.join('\n')}\n\nTHE NEWS, in the project's own words:\n"""${String(news).slice(0, 600)}"""\n\nWrite the announcement post now, following the format exactly.`,
      { tier: 'chat', maxOutputTokens: 500, systemPromptOverride: ANNOUNCE_DRAFT_SYSTEM },
    );
    const text = String(out ?? '').trim();
    return text || null;
  } catch { return null; }
}

function capDraft(text) {
  const t = String(text ?? '').trim();
  if (t.length <= ANN_CAPTION_MAX) return t;
  const cut = t.slice(0, ANN_CAPTION_MAX - 1);
  const nl = cut.lastIndexOf('\n');
  return `${(nl > 200 ? cut.slice(0, nl) : cut).trimEnd()}…`;
}

// ── poster build: card always (free); AI art on the /generate rails ───────
// Returns { note, artBytes } — artBytes are consumed by the preview sender
// in THIS invocation to capture a Telegram file_id; bytes never enter the
// persisted session (config rows are not a media store).
async function buildAnnouncePoster(uid, session, deps = {}) {
  session.poster = session.poster ?? { roll: 0, artFileId: null, visual: 'card', charged: 0 };
  session.poster.roll += 1;
  // OWNER-UNLIMITED (2026-10-29): the owner skips the balance pre-check
  // entirely — reserveImageCredits funds owner jobs at 0, so a 0 balance
  // must not refuse the poster roll before reserve is ever reached.
  const posterOwner = await isOwnerId(uid).catch(() => false);
  const balance = posterOwner ? IMAGE_CREDIT_COST : await imageCreditBalance(uid).catch(() => 0);
  if (balance < IMAGE_CREDIT_COST) {
    // TRIALFIX: the wallet-only refusal must not fire while the 7-day
    // trial covers the image cost — reserveImageCredits already draws
    // week-trial images (image.js), so a covered trial proceeds to
    // reserve below instead of refusing. Owner bypass, refusal text,
    // and price are all unchanged; genuinely-unfunded users (no wallet
    // balance AND no covering trial) still get the exact refusal below.
    const wt = await weekTrialStatus(uid).catch(() => ({ active: false, remaining: 0 }));
    if (!(wt.active && wt.remaining >= IMAGE_CREDIT_COST)) {
      session.poster.artFileId = null;
      session.poster.visual = 'card';
      return {
        note: `🎨 AI art skipped — it costs ${IMAGE_CREDIT_COST} Studio credits and your balance is ${balance}. The typeset card poster below is ready to post. Top up with /buy (Studio credit packs), then tap 🎨 New poster.`,
        artBytes: null,
      };
    }
  }
  const refBase = `announce:${uid}:${session.createdAt}:${session.poster.roll}`;
  // Breaker (wave 3): a breaker-open poster roll falls back to the free
  // card with an honest note — no reserve, no charge, no provider call.
  // This is the one image-generation path that bypasses
  // executeImageCommand, so it gets the same gate here.
  const brk = await (deps.breaker ? deps.breaker() : checkImageBreaker());
  if (brk && !brk.allowed) {
    session.poster.artFileId = null;
    session.poster.visual = 'card';
    return { note: `🎨 ${IMAGE_BREAKER_COPY} The typeset card poster below is ready to post.`, artBytes: null };
  }
  const reserve = deps.reserve ?? reserveImageCredits;
  try {
    // lib/image.js contract: resolves { replay } on success and THROWS on
    // insufficient balance (the balance pre-check above makes that a
    // race-only path). A replay means this exact roll already reserved —
    // settle/refund stay idempotent on the same refBase, so proceeding
    // is safe. OWNER-UNLIMITED: an owner reserve reports { owner: true }
    // and funds at 0, so the session receipt must not record a charge.
    const reserveRes = await reserve(uid, refBase);
    session.poster.ownerFunded = session.poster.ownerFunded || reserveRes?.owner === true;
  } catch (err) {
    session.poster.artFileId = null;
    session.poster.visual = 'card';
    return {
      note: `🎨 AI art skipped — ${err?.message ?? 'not enough Studio credits.'} The typeset card poster below is ready to post.`,
      artBytes: null,
    };
  }
  try {
    const gen = deps.generate ?? ((prompt) => generateGeminiImage(prompt));
    const out = await gen(artPromptFor(session));
    const bytes = out?.bytes ?? out;
    if (!bytes || !bytes.length) throw new Error('empty image from provider');
    const settle = deps.settle ?? settleImageCredits;
    await settle(uid, refBase, true);
    await recordImageBreaker(true);
    if (!session.poster.ownerFunded) session.poster.charged = (session.poster.charged ?? 0) + IMAGE_CREDIT_COST;
    return { note: null, artBytes: bytes };
  } catch (err) {
    const cls = classifyImageError(err);
    if (cls.retryable) await recordImageBreaker(false);
    else releaseImageBreakerTrial();
    const settle = deps.settle ?? settleImageCredits;
    await settle(uid, refBase, false).catch(() => {});
    session.poster.artFileId = null;
    session.poster.visual = 'card';
    return {
      note: session.poster.ownerFunded
        ? '🎨 AI art generation failed — nothing was charged. The typeset card poster below is ready to post.'
        : `🎨 AI art generation failed — your ${IMAGE_CREDIT_COST} Studio credits were refunded in full. The typeset card poster below is ready to post.`,
      artBytes: null,
    };
  }
}

// ── preview rendering ──────────────────────────────────────────────────────
function announcePreviewKeyboard(session) {
  const rows = [[
    { text: '✅ Post it', callback_data: 'ann:post' },
    { text: '✏️ Edit text', callback_data: 'ann:edit' },
  ]];
  const rollRow = [{
    text: session.poster ? `🎨 New poster (${IMAGE_CREDIT_COST}cr)` : `🎨 Generate poster (${IMAGE_CREDIT_COST}cr)`,
    callback_data: 'ann:roll',
  }];
  if (session.poster?.artFileId) rollRow.push({ text: '🔀 Switch visual', callback_data: 'ann:visual' });
  rows.push(rollRow);
  rows.push([{ text: '❌ Cancel', callback_data: 'ann:cancel' }]);
  return { inline_keyboard: rows };
}

function visualLabel(session) {
  if (!session.poster) return '📝 text only (no poster yet)';
  return session.poster.visual === 'art' && session.poster.artFileId ? '🎨 AI art' : '🪪 card poster (typeset headline)';
}

async function sendAnnouncePreview(chatId, uid, session, { note = null, artBytes = null } = {}) {
  if (note) await api.sendMessage({ chat_id: chatId, text: note }).catch(() => {});
  if (artBytes) {
    const artMsg = await api.sendPhoto({
      chat_id: chatId,
      photo: new InputFile(artBytes, 'announce-art.png'),
      caption: '🎨 AI art option for this post — tap 🔀 Switch visual on the preview to post this art instead of the card.',
    }).catch(() => null);
    const photos = artMsg?.photo;
    if (Array.isArray(photos) && photos.length) {
      session.poster.artFileId = photos[photos.length - 1].file_id;
    }
  }
  const kb = announcePreviewKeyboard(session);
  if (session.poster) {
    await api.sendPhoto({
      chat_id: chatId,
      photo: new InputFile(renderPosterBytes(session), 'announce-poster.png'),
      caption: session.draft,
      reply_markup: kb,
    });
  } else {
    await api.sendMessage({ chat_id: chatId, text: session.draft, reply_markup: kb });
  }
  session.previewVisual = visualLabel(session);
  await saveAnnWiz(uid, session);
}

// ── destinations ───────────────────────────────────────────────────────────
let _annMeCache = null;
async function botIsMember(chatId) {
  try {
    if (!_annMeCache) _annMeCache = await api.getMe();
    const m = await api.getChatMember({ chat_id: chatId, user_id: _annMeCache.id });
    return ['member', 'administrator', 'creator'].includes(String(m?.status ?? ''));
  } catch { return false; }
}

async function announceHomeChatId() {
  const raw = String(await getConfig('TELEGRAM_HOME_CHAT_ID', '') ?? '').trim();
  const n = Number(raw);
  return Number.isFinite(n) && n !== 0 ? n : null;
}

async function computeAnnounceDests(uid, session) {
  const dests = [];
  const home = await announceHomeChatId();
  if (session.mode === 'owner') {
    if (home != null) dests.push({ kind: 'home', chatId: home, title: 'Home group' });
    dests.push({ kind: 'allgroups', title: 'All known groups (photo broadcast)' });
    dests.push({ kind: 'blast', title: 'Full blast (groups + DM job)' });
  }
  const mine = await getMyGroupsFor(uid).catch(() => []);
  for (const g of mine.slice(0, 8)) {
    if (home != null && String(g.chatId) === String(home) && session.mode === 'owner') continue;
    if (!(await botIsMember(g.chatId))) continue;
    dests.push({ kind: 'group', chatId: g.chatId, title: g.title });
  }
  return dests;
}

async function messageLinkFor(chatId, messageId) {
  if (!messageId) return null;
  try {
    const c = await api.getChat({ chat_id: chatId });
    if (c?.username) return `https://t.me/${c.username}/${messageId}`;
  } catch { /* fall through */ }
  const s = String(chatId);
  if (s.startsWith('-100')) return `https://t.me/c/${s.slice(4)}/${messageId}`;
  return null;
}

async function sendAnnounceToChat(session, chatId) {
  const caption = session.draft;
  if (session.poster?.visual === 'art' && session.poster?.artFileId) {
    return api.sendPhoto({ chat_id: chatId, photo: session.poster.artFileId, caption });
  }
  if (session.poster) {
    return api.sendPhoto({ chat_id: chatId, photo: new InputFile(renderPosterBytes(session), 'announce-poster.png'), caption });
  }
  return api.sendMessage({ chat_id: chatId, text: caption });
}

async function photoBroadcastPayload(session) {
  if (session.poster?.visual === 'art' && session.poster?.artFileId) return session.poster.artFileId;
  if (session.poster) return new InputFile(renderPosterBytes(session), 'announce-poster.png');
  return null;
}

async function finishAnnouncePost(chatId, uid, session, destTitle, link) {
  const credits = session.poster?.charged ?? 0;
  await pushAnnHist(uid, {
    ts: Date.now(),
    mode: session.mode,
    project: {
      kind: session.project?.kind ?? 'token',
      name: session.project?.name ?? 'Announcement',
      symbol: session.project?.symbol ?? '',
      address: session.project?.address ?? null,
      groupTitle: session.project?.groupTitle ?? null,
    },
    hook: session.hook ?? '',
    news: session.news ?? '',
    draft: session.draft,
    credits,
    destTitle,
    link: link ?? null,
  }).catch(() => {});
  await clearAnnWiz(uid);
  const lines = [`✅ Posted to ${destTitle}.`];
  if (link) lines.push(`🔗 ${link}`);
  lines.push(credits > 0
    ? `🎨 Studio credits charged: ${credits} (poster AI art).`
    : '🎨 No Studio credits charged.');
  lines.push('🗞 Saved to your history — /announce history to see or re-post it.');
  await api.sendMessage({ chat_id: chatId, text: lines.join('\n') }).catch(() => {});
}

// ── wizard steps shared by the command / text / callback drivers ──────────
async function announceProjectChosen(chatId, uid, session) {
  const p = session.project;
  session.step = 'news';
  await saveAnnWiz(uid, session);
  const lines = [`✅ Project locked in: ${p.name}${p.symbol ? ` ($${p.symbol})` : ''} — Base`];
  if (p.priceUsd != null) lines.push(`💵 Live price: ${fmt$(p.priceUsd)} (verified just now)`);
  if (p.address) lines.push(`📍 ${p.address}`);
  if (p.groupTitle) lines.push(`👥 Group: ${p.groupTitle}`);
  lines.push('', '📰 Now tell me the news — what is launching or happening? Send it as one message, in your own words. I will draft the post from exactly that plus the verified facts above — nothing invented.');
  await api.sendMessage({ chat_id: chatId, text: lines.join('\n') });
}

async function announceVerifyCa(chatId, uid, session, address) {
  const facts = await fetchAnnounceTokenFacts(address);
  if (!facts) {
    await api.sendMessage({
      chat_id: chatId,
      text: '❌ I could not verify that contract on Base — no live token data came back for it. Check the address and paste it again, or tap Cancel and start over with /announce.',
      reply_markup: { inline_keyboard: [[{ text: '❌ Cancel', callback_data: 'ann:cancel' }]] },
    });
    return false;
  }
  session.project = {
    kind: 'token', name: facts.name, symbol: facts.symbol,
    address, priceUsd: facts.priceUsd, logoUrl: facts.logoUrl, groupTitle: null,
  };
  await announceProjectChosen(chatId, uid, session);
  return true;
}

async function announceDraftAndPreview(chatId, uid, session, deps) {
  const draft = await draftAnnouncement(session.project, session.news, deps);
  if (!draft) {
    await api.sendMessage({
      chat_id: chatId,
      text: '⚠️ The draft did not come back. Your news is saved — try again, or write the post text yourself.',
      reply_markup: {
        inline_keyboard: [[
          { text: '🔁 Try again', callback_data: 'ann:retry' },
          { text: '✏️ Write it myself', callback_data: 'ann:edit' },
        ], [{ text: '❌ Cancel', callback_data: 'ann:cancel' }]],
      },
    });
    return;
  }
  session.draft = capDraft(draft);
  session.step = 'draft';
  const built = await buildAnnouncePoster(uid, session, deps);
  await sendAnnouncePreview(chatId, uid, session, built);
}

// ── /announce command ──────────────────────────────────────────────────────
async function loadBotUserRow(uid) {
  const rows = await db.select().from(bot_users)
    .where(eq(bot_users.telegramUserId, String(uid))).limit(1).all();
  return rows[0] ?? null;
}

async function announceGate(uid) {
  const owner = await isOwnerId(uid).catch(() => false);
  const row = await loadBotUserRow(uid);
  const tier = await effectiveTier(uid, row);
  return { owner, tier, allowed: owner || tierAtLeast(tier, 'starter') };
}

async function sendAnnounceHistory(chatId, uid) {
  const hist = await loadAnnHist(uid);
  if (!hist.length) {
    await api.sendMessage({ chat_id: chatId, text: '🗞 No announcements yet. Run /announce to make your first one.' });
    return;
  }
  const lines = ['🗞 Your recent announcements — tap one to re-post it:'];
  const kb = [];
  hist.forEach((h, i) => {
    const when = new Date(h.ts).toISOString().slice(0, 10);
    lines.push('', `${i + 1}. ${h.project?.name ?? 'Announcement'} → ${h.destTitle ?? ''} (${when})`,
      String(h.draft ?? '').split('\n')[0].slice(0, 90));
    kb.push([{ text: `♻️ Re-post #${i + 1}: ${String(h.project?.name ?? 'post').slice(0, 24)}`, callback_data: `ann:hist:${i}` }]);
  });
  await api.sendMessage({ chat_id: chatId, text: lines.join('\n'), reply_markup: { inline_keyboard: kb } });
}

async function cmdAnnounce(chatId, args, from) {
  const uid = Number(from?.id);
  if (!uid) return;
  const gate = await announceGate(uid);
  if (!gate.allowed) {
    await api.sendMessage({
      chat_id: chatId,
      text: `${tierGateReply(gate.tier, 'announce')}\n\n📣 PB Announce builds a graphic announcement post — poster + structured caption — for your token or product.`,
    }).catch(() => {});
    return;
  }
  const argText = String(args ?? '').trim();
  if (argText.toLowerCase() === 'history') { await sendAnnounceHistory(chatId, uid); return; }
  const mode = gate.owner ? 'owner' : 'user';
  const session = {
    v: 1, step: 'who', mode, chatId, createdAt: Date.now(), expiresAt: 0,
    project: null, news: null, hook: '', draft: null, poster: null, dests: null, groupChoices: null,
  };
  await saveAnnWiz(uid, session);
  if (BASE_CA_RE.test(argText)) { await announceVerifyCa(chatId, uid, session, argText); return; }
  const rows = [];
  if (mode === 'owner') rows.push([{ text: '🤖 PoorBoyAI product', callback_data: 'ann:pb' }]);
  rows.push([{ text: '🪙 A token — paste its CA', callback_data: 'ann:token' }]);
  rows.push([{ text: '👥 A group I admin', callback_data: 'ann:group' }]);
  rows.push([{ text: '❌ Cancel', callback_data: 'ann:cancel' }]);
  await api.sendMessage({
    chat_id: chatId,
    text: mode === 'owner'
      ? '📣 PB Announce — let\'s build the post.\n\nWhose announcement is this?'
      : '📣 PB Announce — let\'s build your announcement post: a graphic poster + a structured caption, in your project\'s branding.\n\nPick your project:',
    reply_markup: { inline_keyboard: rows },
  });
}

export const ANNOUNCE_COMMANDS = {
  announce: async (chatId, args, msg) => { await cmdAnnounce(chatId, args, msg?.from); },
};

// ── wizard text capture (DM; steps ca / news / edit consume plain text) ───
export async function handleAnnounceWizardText(chatId, user, text, deps = {}) {
  const uid = Number(user?.id);
  if (!uid || !text) return false;
  const session = await loadAnnWiz(uid);
  if (!session) return false;
  const body = String(text).trim();

  if (session.step === 'ca') {
    if (!BASE_CA_RE.test(body)) {
      await api.sendMessage({
        chat_id: chatId,
        text: 'That does not look like a Base contract address (0x + 40 hex characters). Paste the CA again, or tap Cancel.',
        reply_markup: { inline_keyboard: [[{ text: '❌ Cancel', callback_data: 'ann:cancel' }]] },
      }).catch(() => {});
      return true;
    }
    await announceVerifyCa(chatId, uid, session, body);
    return true;
  }

  if (session.step === 'news') {
    session.news = body.slice(0, 600);
    session.hook = body.split('\n')[0].replace(/\s+/g, ' ').slice(0, 60).trim();
    await saveAnnWiz(uid, session);
    await announceDraftAndPreview(chatId, uid, session, deps);
    return true;
  }

  if (session.step === 'edit') {
    if (body.length > ANN_CAPTION_MAX) {
      await api.sendMessage({
        chat_id: chatId,
        text: `That is ${body.length} characters — a photo caption caps at ~${ANN_CAPTION_MAX}. Shorten it and send again; your exact words are used, nothing is rewritten.`,
      }).catch(() => {});
      return true;
    }
    // Edit loop law: the replacement text is used EXACTLY as written.
    session.draft = body;
    session.step = 'draft';
    await saveAnnWiz(uid, session);
    await sendAnnouncePreview(chatId, uid, session, {});
    return true;
  }

  return false;
}

// ── callbacks (ann:*) — returns { text, alert } for the router ────────────
export async function handleAnnounceCallback(query, deps = {}) {
  const uid = Number(query?.from?.id);
  const chatId = query?.message?.chat?.id;
  const data = String(query?.data ?? '');
  if (!uid || chatId == null) return { text: 'That button is stale.', alert: true };
  const session = await loadAnnWiz(uid);
  const action = data.slice('ann:'.length);

  if (action === 'cancel') {
    await clearAnnWiz(uid);
    await api.sendMessage({ chat_id: chatId, text: '❌ Announcement cancelled. Nothing was posted and no credits were charged for the cancel.' }).catch(() => {});
    return { text: 'Cancelled.' };
  }
  // History re-post is reachable with NO live session (the history list
  // is a standalone view), so it is handled before the session guard.
  if (action.startsWith('hist:')) {
    const entry = (await loadAnnHist(uid))[Number(action.slice(5))];
    if (!entry) return { text: 'That history entry is gone.', alert: true };
    const fresh = {
      v: 1, step: 'draft', mode: (await isOwnerId(uid).catch(() => false)) ? 'owner' : 'user',
      chatId, createdAt: Date.now(), expiresAt: 0,
      project: entry.project, news: entry.news ?? '', hook: entry.hook ?? '',
      draft: entry.draft, poster: null, dests: null, groupChoices: null,
    };
    await saveAnnWiz(uid, fresh);
    await api.sendMessage({ chat_id: chatId, text: '♻️ Loaded from your history. Post it as-is, re-roll a poster (2cr for the AI art), or edit the text first.' }).catch(() => {});
    await sendAnnouncePreview(chatId, uid, fresh, {});
    return { text: 'Loaded from history.' };
  }
  if (!session) return { text: 'That announcement expired — run /announce again.', alert: true };

  try {
    if (action === 'pb') {
      if (session.mode !== 'owner') return { text: 'Owner mode only.', alert: true };
      const facts = await fetchAnnounceTokenFacts(PBAI_CA).catch(() => null);
      session.project = {
        kind: 'pb', name: 'PoorBoyAI', symbol: 'PBAI', address: PBAI_CA,
        priceUsd: facts?.priceUsd ?? null, logoUrl: facts?.logoUrl ?? null, groupTitle: null,
      };
      await announceProjectChosen(chatId, uid, session);
      return { text: 'PB product mode.' };
    }

    if (action === 'token') {
      session.step = 'ca';
      await saveAnnWiz(uid, session);
      await api.sendMessage({
        chat_id: chatId,
        text: '🪙 Paste the token\'s Base contract address (0x…). I verify it live — name, symbol and price — before anything is drafted.',
        reply_markup: { inline_keyboard: [[{ text: '❌ Cancel', callback_data: 'ann:cancel' }]] },
      });
      return { text: 'Paste the CA.' };
    }

    if (action === 'group') {
      const mine = await getMyGroupsFor(uid).catch(() => []);
      if (!mine.length) {
        await api.sendMessage({ chat_id: chatId, text: 'No groups found where you are an admin and PB is present. Add PB to your group, make sure you are an admin there, then run /announce again — or pick the token CA route.' });
        return { text: 'No admin groups found.', alert: true };
      }
      session.groupChoices = mine.slice(0, 8).map((g) => ({ chatId: g.chatId, title: g.title }));
      session.step = 'grouppick';
      await saveAnnWiz(uid, session);
      await api.sendMessage({
        chat_id: chatId,
        text: '👥 Which group is this announcement for?',
        reply_markup: {
          inline_keyboard: [
            ...session.groupChoices.map((g, i) => [{ text: String(g.title).slice(0, 30), callback_data: `ann:grp:${i}` }]),
            [{ text: '❌ Cancel', callback_data: 'ann:cancel' }],
          ],
        },
      });
      return { text: 'Pick the group.' };
    }

    if (action.startsWith('grp:')) {
      const pick = (session.groupChoices ?? [])[Number(action.slice(4))];
      if (!pick) return { text: 'That group pick expired — run /announce again.', alert: true };
      const settings = await getGroupSettings(pick.chatId).catch(() => ({}));
      const featured = settings?.tokenAddress && BASE_CA_RE.test(String(settings.tokenAddress))
        ? await fetchAnnounceTokenFacts(String(settings.tokenAddress)).catch(() => null)
        : null;
      session.project = {
        kind: 'group',
        name: featured?.name || pick.title,
        symbol: featured?.symbol || '',
        address: featured ? String(settings.tokenAddress) : null,
        priceUsd: featured?.priceUsd ?? null,
        logoUrl: featured?.logoUrl ?? null,
        groupTitle: pick.title,
      };
      await announceProjectChosen(chatId, uid, session);
      return { text: 'Group picked.' };
    }

    if (action === 'retry') {
      if (!session.news) return { text: 'No news saved yet.', alert: true };
      await announceDraftAndPreview(chatId, uid, session, deps);
      return { text: 'Drafting again…' };
    }

    if (action === 'edit') {
      session.step = 'edit';
      await saveAnnWiz(uid, session);
      await api.sendMessage({
        chat_id: chatId,
        text: session.draft
          ? '✏️ Send the replacement text now — it will be posted exactly as you write it, word for word.'
          : '✏️ Send the full post text now — it will be posted exactly as you write it, word for word.',
      });
      return { text: 'Send the replacement text.' };
    }

    if (action === 'roll') {
      if (!session.draft) return { text: 'Draft the post first.', alert: true };
      const built = await buildAnnouncePoster(uid, session, deps);
      await sendAnnouncePreview(chatId, uid, session, built);
      return { text: 'New poster rolled.' };
    }

    if (action === 'visual') {
      if (!session.poster?.artFileId) return { text: 'No AI art on this poster yet.', alert: true };
      session.poster.visual = session.poster.visual === 'art' ? 'card' : 'art';
      await saveAnnWiz(uid, session);
      return { text: `Posting visual: ${visualLabel(session)}`, alert: true };
    }

    if (action === 'post') {
      if (!session.draft) return { text: 'Nothing to post yet.', alert: true };
      const dests = await computeAnnounceDests(uid, session);
      session.dests = dests;
      session.step = 'dest';
      await saveAnnWiz(uid, session);
      if (!dests.length) {
        await api.sendMessage({
          chat_id: chatId,
          text: '📤 No destinations yet: I can only post to groups where YOU are an admin and PB is a member. Add PB to your group and make sure you hold admin there, then tap Post it again.',
          reply_markup: {
            inline_keyboard: [[
              { text: '⬅️ Back to preview', callback_data: 'ann:back' },
              { text: '❌ Cancel', callback_data: 'ann:cancel' },
            ]],
          },
        });
        return { text: 'No destinations available.', alert: true };
      }
      await api.sendMessage({
        chat_id: chatId,
        text: `📤 Where should this post go?\n\nVisual: ${visualLabel(session)}\nPost starts: “${String(session.draft).split('\n')[0].slice(0, 80)}”`,
        reply_markup: {
          inline_keyboard: [
            ...dests.map((d, i) => [{ text: `📣 ${String(d.title).slice(0, 28)}`, callback_data: `ann:dest:${i}` }]),
            [
              { text: '⬅️ Back to preview', callback_data: 'ann:back' },
              { text: '❌ Cancel', callback_data: 'ann:cancel' },
            ],
          ],
        },
      });
      return { text: 'Pick a destination.' };
    }

    if (action === 'back') {
      session.step = 'draft';
      await saveAnnWiz(uid, session);
      await sendAnnouncePreview(chatId, uid, session, {});
      return { text: 'Back to the preview.' };
    }

    if (action.startsWith('dest:')) {
      const dest = (session.dests ?? [])[Number(action.slice(5))];
      if (!dest) return { text: 'That destination expired — tap Post it again.', alert: true };
      if (!session.draft) return { text: 'Nothing to post.', alert: true };

      if (dest.kind === 'group' || dest.kind === 'home') {
        // Send-time re-verification (sealed communities): the caller must
        // STILL admin the group and PB must STILL be a member. Owner home
        // posts skip the admin re-check only for the home group itself.
        if (dest.kind === 'group') {
          const stillAdmin = await isChatAdmin(dest.chatId, uid).catch(() => false);
          if (!stillAdmin) {
            await api.sendMessage({ chat_id: chatId, text: `⛔ Not posted: you are not an admin of ${dest.title} (checked live just now), so PB will not post there.` });
            return { text: 'Not an admin there.', alert: true };
          }
        }
        if (!(await botIsMember(dest.chatId))) {
          await api.sendMessage({ chat_id: chatId, text: `⛔ Not posted: PB is not a member of ${dest.title} right now.` });
          return { text: 'PB is not in that group.', alert: true };
        }
        const sent = await sendAnnounceToChat(session, dest.chatId);
        const link = await messageLinkFor(dest.chatId, sent?.message_id);
        await finishAnnouncePost(chatId, uid, session, dest.title, link);
        return { text: 'Posted.' };
      }

      if (dest.kind === 'allgroups' || dest.kind === 'blast') {
        const photo = await photoBroadcastPayload(session);
        let groupsLine;
        if (photo) {
          const r = await executePhotoBroadcast(photo, session.draft);
          // Photo-broadcast placeholder guard (W2, 2026-10-30): mirror the
          // text leg below — a refused photo run reports refused and
          // returns BEFORE finishAnnouncePost (no history row, draft stays
          // editable) and BEFORE the blast DM-leg job, never "sent".
          if (r.refused) {
            await api.sendMessage({ chat_id: chatId, text: '⛔ Broadcast refused — the draft looks like a placeholder. Nothing sent. Edit the draft and try again.' });
            return { text: 'Broadcast refused — nothing sent.', alert: true };
          }
          groupsLine = `groups ${r.sent}/${r.total} (${r.failed} failed)`;
        } else {
          const r = await executeBroadcast(session.draft);
          if (r.refused) {
            await api.sendMessage({ chat_id: chatId, text: '⛔ Broadcast refused — the draft looks like a placeholder. Nothing sent. Edit the draft and try again.' });
            return { text: 'Broadcast refused — nothing sent.', alert: true };
          }
          groupsLine = `groups ${r.sent}/${r.total} (${r.failed} failed)`;
        }
        let title = `Broadcast — ${groupsLine}`;
        if (dest.kind === 'blast') {
          const job = await createDmBroadcastJob(session.draft, uid);
          title += job?.ok
            ? ` · DM job #${job.jobId} queued (${job.recipients} recipients, text version)`
            : ` · DM leg not queued (${job?.error ?? 'broadcast already running'})`;
        }
        await finishAnnouncePost(chatId, uid, session, title, null);
        return { text: 'Broadcast sent.' };
      }

      return { text: 'Unknown destination.', alert: true };
    }

    return { text: 'Unknown announce action.', alert: true };
  } catch (err) {
    console.warn('announce callback failed', err);
    return { text: 'Something failed — your draft is saved, try again.', alert: true };
  }
}

